// ---- merged-geometry helpers (the whole static city becomes 2 draw calls) ----
function colorGeo(geo, hex) {
  const c = new THREE.Color(hex);
  const n = geo.attributes.position.count;
  const arr = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { arr[i * 3] = c.r; arr[i * 3 + 1] = c.g; arr[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  return geo;
}
function placeGeo(geo, x, y, z, ry = 0) {
  if (ry) geo.rotateY(ry);
  geo.translate(x, y, z);
  return geo;
}
const windowGeos = [];   // textured (windows) + vertex colours
const flatGeos = [];     // untextured vertex colours

// ground
{
  const g = new THREE.Mesh(new THREE.PlaneGeometry(HALF * 2 + 400, HALF * 2 + 400), MAT.road);
  g.rotation.x = -Math.PI / 2; g.receiveShadow = true; worldGroup.add(g);
}

// sidewalks (one slab per block, slightly raised)
for (let i = 0; i < NBLOCKS; i++) for (let j = 0; j < NBLOCKS; j++) {
  const cx = nodeX(i) + CELL / 2, cz = nodeX(j) + CELL / 2;
  flatGeos.push(colorGeo(placeGeo(new THREE.BoxGeometry(CELL - ROAD + 2, 0.35, CELL - ROAD + 2), cx, 0.175, cz), 0xb9b9b4));
}

