    : [[cx - 8.5, cz - 8.5, 13, 13], [cx + 8.5, cz - 8.5, 13, 13], [cx, cz + 9.5, CELL - ROAD - 8, 11]];
  for (const [bx, bz, bw, bd] of lots) {
