function buildCarMesh(color, type) {
  const g = new THREE.Group();
  const parts = [];
  const add = (w, h, d, x, y, z, hex, ry = 0) =>
    parts.push(colorGeo(placeGeo(new THREE.BoxGeometry(w, h, d), x, y, z, ry), hex));
  const roofCol = new THREE.Color(color).multiplyScalar(0.85).getHex();
  add(1.9, 0.75, 4.4, 0, 0.72, 0, color);                        // chassis
  add(1.75, 0.16, 2.25, 0, 1.68, -0.15, roofCol);               // roof
  if (type === 'taxi') add(1.1, 0.4, 0.5, 0, 1.95, -0.15, 0x222222);
  if (type === 'police') add(1.9, 0.35, 1.2, 0, 0.45, 0.4, 0x15151a);
  add(0.5, 0.22, 0.1, -0.6, 0.72, 2.22, 0xfff3b0);              // headlights
  add(0.5, 0.22, 0.1, 0.6, 0.72, 2.22, 0xfff3b0);
  add(0.5, 0.22, 0.1, -0.6, 0.72, -2.22, 0xff4444);            // taillights
  add(0.5, 0.22, 0.1, 0.6, 0.72, -2.22, 0xff4444);
  // wheels
